// generated by eider: loader for long.wasm
export async function load(wasm, imports = {}) {
  let mem;
  const dec = new TextDecoder();
  const env = {
    eider_write(p, n) { (typeof process !== 'undefined' ? process.stdout.write.bind(process.stdout) : console.log)(dec.decode(new Uint8Array(mem.buffer, p, n))); },
    eider_now_ms() { return BigInt(Date.now()); },
    ...imports,
  };
  const src = wasm instanceof WebAssembly.Module ? wasm : await WebAssembly.compile(wasm);
  const inst = await WebAssembly.instantiate(src, { env });
  mem = inst.exports.memory;
  const x = inst.exports;
  return {
    long_line: (n) => x.eider_long_line(n),
  };
}
